<?php declare(strict_types=1);require_once __DIR__.'/bootstrap.php';$items=(new App\History())->all();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>History</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="assets/css/app.css" rel="stylesheet"></head><body><aside class="sidebar"><div class="brand">Student Compare</div><a href="index.php">Compare</a><a class="active" href="history.php">History</a><a href="settings.php">Settings</a></aside><main class="content"><h2>Comparison History</h2><div class="card border-0 shadow-sm mt-4"><div class="card-body table-responsive"><table class="table"><thead><tr><th>Date</th><th>File A</th><th>File B</th><th>Mode</th><th>Matched</th><th>Modified</th><th>Hash</th></tr></thead><tbody><?php foreach($items as $i):$s=$i['summary']??[];?><tr><td><?=e($i['created_at']??'')?></td><td><?=e($i['file_a']??'')?></td><td><?=e($i['file_b']??'')?></td><td><?=e($i['mode']??'')?></td><td><?=e($s['matched']??0)?></td><td><?=e($s['modified']??0)?></td><td><code><?=e(substr($i['hash']??'',0,16))?></code></td></tr><?php endforeach;?></tbody></table></div></div></main></body></html>
